package com.vandorlabs.neoforge.copifier;

import com.vandorlabs.neoforge.*;
import com.vandorlabs.neoforge.screen.*;
import com.vandorlabs.persistence.*;
import com.vandorlabs.redstone.*;
import com.vandorlabs.screen.ScreenFamily;
import java.util.*;
import net.minecraft.nbt.*;

/** Bounded Screen clipboard values. No physical chip, journal page, pulse deadline or latch bank enters a plan. */
public final class NativeCopifierScreenEdit {
 public record Row(String label,ChannelList channels,boolean slider,boolean pulse,int min,int max){}
 public record Rows(boolean enabled,String title,List<Row> rows){public Rows{rows=List.copyOf(rows);if(rows.size()>8)throw new IllegalArgumentException("Screen copy rows");}public CompoundTag configuration(){var out=new CompoundTag();out.putBoolean("Enabled",enabled);out.putString("Title",title);var list=new ListTag();for(var row:rows){var e=new CompoundTag();e.putString("Label",row.label);e.putIntArray("RedstoneChannels",row.channels.toArray());e.putBoolean("Slider",row.slider);e.putBoolean("Pulse",row.pulse);e.putInt("Min",row.min);e.putInt("Max",row.max);list.add(e);}out.put("Rows",list);return out;}public Rows enabled(boolean next){return next==enabled?this:new Rows(next,title,rows);}}
 public record State(ScreenFamily family,NativeScreenSettings settings,FrameSettings frames,List<Rows> controls,NativeScreenEntity.Transmission transmission){public State{controls=List.copyOf(controls);if(controls.size()!=2)throw new IllegalArgumentException("Screen copy slots");}}
 public record RowEdit(boolean enabled,NativeScreenRowEdit choices){}
 public record Plan(boolean applicable,State scalar,State result,List<RowEdit> rows,boolean surface0,boolean surface1,boolean activation){public Plan{rows=rows==null?null:List.copyOf(rows);}public CompoundTag capture(){return NativeCopifierScreenEdit.capture(result);}}
 public static State read(ScreenFamily family,CompoundTag root){return read(family,root,true);}
 public static State readItem(ScreenFamily family,CompoundTag root){return read(family,root,false);}
 private static State read(ScreenFamily family,CompoundTag root,boolean placed){var c=NativeScreenCatalog.INSTANCE;var tag=NativeScreenArtworkMigration.normalize(root,c);var fields=new ModernHousingTags(tag);var settings=NativeScreenSettings.read(tag,c);var frames=FrameSettings.read(fields,c::validFrame,c::validFrameSurface,c::validMaterial);var controls=java.util.List.of(NativeScreenControls.read(tag.getCompound("RedstonePrimary"),placed?family.standaloneControlRows(0):8),NativeScreenControls.read(tag.getCompound("RedstoneSecondary"),placed?family.standaloneControlRows(1):8));var t=tag.getCompound("ForgeData").getCompound(TransmissionSettings.SETTINGS).getCompound("main");var transmission=new NativeScreenEntity.Transmission(TransmissionSettings.readRange(t.contains("Range",Tag.TAG_INT),t.getInt("Range"),true),TransmissionSettings.readLocal(t.contains("Local",Tag.TAG_BYTE),t.getBoolean("Local"),false),TransmissionSettings.readChannels(t.contains("Channels",Tag.TAG_INT_ARRAY),t.getIntArray("Channels"),ChannelList.EMPTY));return state(family,settings,frames,controls,transmission);}
 public static State state(ScreenFamily family,NativeScreenSettings settings,FrameSettings frames,List<NativeScreenControls> controls,NativeScreenEntity.Transmission transmission){var out=new ArrayList<Rows>(2);for(var header:controls){var rows=new ArrayList<Row>();for(var r:header.rows())rows.add(new Row(r.label(),r.channels(),r.slider(),r.pulse(),r.min(),r.max()));out.add(new Rows(header.enabled(),header.title(),rows));}return new State(family,settings,frames,out,transmission);}
 private static final NativeScreenCatalog C=NativeScreenCatalog.INSTANCE;
 public static CompoundTag capture(NativeScreenEntity owner){return capture(owner.copiedSettings());}
 public static CompoundTag capture(State state){var s=state.settings;var d=s.scalar();var out=new CompoundTag();out.putInt("wall_texture",s.housing().mainTexture);out.putInt("primary_surface",state.controls.get(0).enabled?-2:s.primarySurface());out.putInt("secondary_surface",state.controls.get(1).enabled?-2:s.secondarySurface());var activation=new CompoundTag();s.activation().write(activation);out.put("display_activation",activation);out.putString("primary_kind","screen");out.putString("primary_texture",C.canonicalScreen(d.selectedScreen));out.putInt("redstone_trigger",d.redstoneEnabled?s.inverted()?2:1:0);out.putInt("display_mode",d.displayMode);out.putInt("animation_speed",d.animationSpeedIndex);out.putBoolean("framed",d.framed);out.putString("input_panel",C.canonicalInput(d.inputPanel));out.putString("secondary_input_panel",C.canonicalInput(d.secondaryInputPanel));out.putBoolean("small_input",d.smallInput);out.putInt("wall_position",d.wallPosition<0?1:d.wallPosition);out.putBoolean("slab_tile_sides",s.surfaceTileSides());out.putInt("texture_layout",s.surfaceLayout());var pair=new CompoundTag();pair.put("Primary",state.controls.get(0).configuration());pair.put("Secondary",state.controls.get(1).configuration());out.put("redstone_rows",pair);var frames=new CompoundTag();state.frames.write(new ModernHousingTags(frames));out.put("FrameAppearance",frames);var bank=s.channels();if(bank.size()<=1)out.putInt("redstone_channel",bank.first());else out.putIntArray("redstone_channel",bank.toArray());var tx=new CompoundTag();tx.putIntArray("Channels",state.transmission.channels().toArray());tx.putInt("Range",state.transmission.range());tx.putBoolean("Local",state.transmission.local());out.put("Transmission",tx);return out;}
 private static boolean flag(CompoundTag values,String key,boolean old){return values.contains(key,Tag.TAG_BYTE)?values.getBoolean(key):old;}
 private static int number(CompoundTag values,String key,int old){return values.contains(key,Tag.TAG_INT)?values.getInt(key):old;}
 private static NativeScreenSettings copy(NativeScreenSettings old,ScreenData data,NativeScreenActivation activation,boolean inverted,int primary,int secondary,int layout,boolean tile,ChannelList channels){return new NativeScreenSettings(data,old.housing().withMainTexture(data.housingTexture),activation,channels,old.channelLevel(),inverted,primary,secondary,old.ceilingMounted(),old.ceilingPosition(),layout,tile);}
 private static Rows options(CompoundTag input,int capacity,boolean enabled){var parsed=NativeScreenControls.read(input,capacity);var out=new ArrayList<Row>();for(var row:parsed.rows())out.add(new Row(row.label().trim(),row.channels(),row.slider(),row.pulse(),row.min(),row.max()));return new Rows(enabled,input.getString("Title").trim(),out);}
 private static NativeScreenRowEdit edit(Rows rows){var out=new ArrayList<NativeScreenRowEdit.Row>();for(var row:rows.rows)out.add(new NativeScreenRowEdit.Row(row.label,row.channels,row.slider,row.pulse,row.min,row.max));return new NativeScreenRowEdit(rows.title,out);}
 public static Plan prepare(State current,CompoundTag values){return prepare(current,values,true);}
 public static Plan prepareItem(State current,CompoundTag values){return prepare(current,values,false);}
 private static Plan prepare(State current,CompoundTag values,boolean placed){
  if(values==null)values=new CompoundTag();if(!NativeCopiedSettingsValidation.valid(values))throw new IllegalArgumentException("Invalid Screen clipboard");for(String key:new String[]{"primary_surface","secondary_surface"})if(values.contains(key,Tag.TAG_INT)&&values.getInt(key)==-3)throw new IllegalArgumentException("Vehicle surface is not converted");
  var old=current.settings;var d=old.scalar();boolean applicable=false;int housing=d.housingTexture;var activation=old.activation();int primary=old.primarySurface(),secondary=old.secondarySurface();var controls=new ArrayList<>(current.controls);boolean p0=values.contains("primary_surface",Tag.TAG_INT),p1=values.contains("secondary_surface",Tag.TAG_INT);
  if(values.contains("wall_texture",Tag.TAG_INT)){housing=C.material(values.getInt("wall_texture"));applicable=true;}
  boolean activated=values.contains("display_activation",Tag.TAG_COMPOUND);if(activated){activation=NativeScreenActivation.read(values.getCompound("display_activation"));applicable=true;}
  for(int slot=0;slot<2;slot++)if(slot==0?p0:p1){int choice=values.getInt(slot==0?"primary_surface":"secondary_surface"),raw=slot==0?primary:secondary;if(choice!=-2)raw=choice==-4?-4:choice<0?-1:C.material(choice);controls.set(slot,controls.get(slot).enabled(choice==-2));if(slot==0)primary=raw;else secondary=raw;applicable=true;}
  String selected=d.selectedScreen;if("screen".equals(values.getString("primary_kind"))&&values.contains("primary_texture",Tag.TAG_STRING)&&C.validScreen(values.getString("primary_texture"))){String candidate=values.getString("primary_texture");if(!Objects.equals(C.canonicalScreen(selected),C.canonicalScreen(candidate)))selected=candidate;applicable=true;}
  boolean enabled=d.redstoneEnabled,inverted=old.inverted();int trigger=number(values,"redstone_trigger",-1);if(trigger>=0&&trigger<=2){enabled=trigger!=0;if(activation.data().mode>=0)activation=new NativeScreenActivation(activation.data().withMode(enabled?Math.max(1,activation.data().mode):0));inverted=trigger==2;applicable=true;}
  String input=d.inputPanel,second=d.secondaryInputPanel;for(int slot=0;slot<2;slot++){String key=slot==0?"input_panel":"secondary_input_panel";if(values.contains(key,Tag.TAG_STRING)){String candidate=values.getString(key);if(!C.validInput(candidate))candidate=C.defaultInput();if(slot==0){if(!Objects.equals(C.canonicalInput(input),C.canonicalInput(candidate)))input=candidate;}else if(!Objects.equals(C.canonicalInput(second),C.canonicalInput(candidate)))second=candidate;applicable=true;}}
  for(String key:new String[]{"display_mode","animation_speed","wall_position"})applicable|=values.contains(key,Tag.TAG_INT);for(String key:new String[]{"framed","small_input"})applicable|=values.contains(key,Tag.TAG_BYTE);
  int wall=values.contains("wall_position",Tag.TAG_INT)?Math.max(0,Math.min(2,values.getInt("wall_position"))):d.wallPosition;
  var data=new ScreenData(selected,enabled,number(values,"display_mode",d.displayMode),flag(values,"framed",d.framed),number(values,"animation_speed",d.animationSpeedIndex),input,second,wall,flag(values,"small_input",d.smallInput),d.redstoneChannel,d.channelSignal,housing);
  int layout=old.surfaceLayout();boolean tile=old.surfaceTileSides();if(values.contains("texture_layout",Tag.TAG_INT)){int next=values.getInt("texture_layout");if(layout!=next){layout=next;tile=next==1;}applicable=true;}else if(values.contains("slab_tile_sides",Tag.TAG_BYTE)){boolean next=values.getBoolean("slab_tile_sides");if(tile!=next){tile=next;layout=next?1:0;}applicable=true;}
  var scalarSettings=copy(old,data,activation,inverted,primary,secondary,layout,tile,old.channels());var scalar=new State(current.family,scalarSettings,current.frames,controls,current.transmission);
  List<RowEdit> edits=null;if(values.contains("redstone_rows",Tag.TAG_COMPOUND)){var pair=values.getCompound("redstone_rows");if(pair.contains("Primary",Tag.TAG_COMPOUND)&&pair.contains("Secondary",Tag.TAG_COMPOUND)&&NativeScreenControls.validConfiguration(pair.getCompound("Primary"))&&NativeScreenControls.validConfiguration(pair.getCompound("Secondary"))){edits=new ArrayList<>();for(int slot=0;slot<2;slot++){var raw=pair.getCompound(slot==0?"Primary":"Secondary");var header=options(raw,placed?current.family.standaloneControlRows(slot):8,placed&&raw.getBoolean("Enabled")&&current.family.supportsSlot(slot));controls.set(slot,header);edits.add(new RowEdit(header.enabled,edit(header)));}applicable=true;}}
  var channels=old.channels();if(values.contains("redstone_channel")){if(values.contains("redstone_channel",Tag.TAG_INT_ARRAY))try{channels=ChannelList.of(values.getIntArray("redstone_channel"));}catch(IllegalArgumentException malformed){/* Source receiver fallback. */}else if(values.contains("redstone_channel",Tag.TAG_INT))channels=ChannelList.of(Math.max(0,values.getInt("redstone_channel")));applicable=true;}
  data=new ScreenData(data.selectedScreen,data.redstoneEnabled,data.displayMode,data.framed,data.animationSpeedIndex,data.inputPanel,data.secondaryInputPanel,data.wallPosition,data.smallInput,channels.first(),data.channelSignal,data.housingTexture);var settings=copy(old,data,activation,inverted,primary,secondary,layout,tile,channels);
  var frames=current.frames;if(values.contains("FrameAppearance",Tag.TAG_COMPOUND)){frames=FrameSettings.read(new ModernHousingTags(values.getCompound("FrameAppearance")),C::validFrame,C::validFrameSurface,C::validMaterial);if(current.family.displayArtwork)frames=new FrameSettings(frames.front,frames.interior,frames.exterior,1,frames.splitTop,frames.splitBottom,frames.tile,frames.displayFit,frames.split,frames.bare);applicable=true;}
  var transmission=current.transmission;if(values.contains("Transmission",Tag.TAG_COMPOUND)){var tx=values.getCompound("Transmission");transmission=new NativeScreenEntity.Transmission(tx.getInt("Range"),tx.getBoolean("Local"),ChannelList.of(tx.getIntArray("Channels")));applicable=true;}
  return new Plan(applicable,scalar,new State(current.family,settings,frames,controls,transmission),edits,p0,p1,activated);
 }
 private NativeCopifierScreenEdit(){}
}
